"""Dungeon Game — DP backwards from the princess.

Forward DP fails because maximising health so far can strand the knight later;
working right-to-left computes the minimum health *required* on entry.

Time: O(m*n)   Space: O(m*n)
"""
from typing import List


class Solution:
    def calculateMinimumHP(self, dungeon: List[List[int]]) -> int:
        m, n = len(dungeon), len(dungeon[0])
        need = [[float("inf")] * (n + 1) for _ in range(m + 1)]
        need[m][n - 1] = need[m - 1][n] = 1
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                required = min(need[i + 1][j], need[i][j + 1]) - dungeon[i][j]
                need[i][j] = max(1, required)
        return need[0][0]
